import fs from 'node:fs';
import path from 'node:path';
import {pathToFileURL} from 'node:url';
const root=process.cwd();
const {readExam}=await import(pathToFileURL(path.join(root,'archive/tools/archive-codex-artifact-io.mjs')));
const evidence=path.join(root,'archive/analysis/archive-2026-1mid-nine-20261008/26_동산중_1학기_중간_중2_기출');
const tmp=path.join(root,'.tmp/archive/archive-2026-1mid-nine-20261008/26_동산중_1학기_중간_중2_기출');
const currentPath=path.join(tmp,'26_동산중_1학기_중간_중2_기출.js');
const basePath=path.join(tmp,'CREATE.item-recovery.current-student.bundle.json');
const q21Path=path.join(tmp,'R1.scope-21@recovery-02.json');
const inputOut=path.join(tmp,'R1.current-full24.student.input.json');
const assignment=JSON.parse(fs.readFileSync(path.join(evidence,'R1.assignment.json')));
const current=readExam(currentPath);
const base=JSON.parse(fs.readFileSync(basePath));
const q21=JSON.parse(fs.readFileSync(q21Path));
if(base.schemaVersion!=='JS_ARCHIVE_STUDENT_BUNDLE_V2'||base.questionCount!==24||base.sourceRawSha256!=='5253521b97afb93dec752e0ad28e361ca35a3e5f5dbfef8e26889142fe876633') throw new Error('BASELINE_STUDENT_BUNDLE_BINDING_INVALID');
if(q21.schemaVersion!=='JS_ARCHIVE_STUDENT_BUNDLE_V2'||q21.questionCount!==1||q21.qids?.length!==1||q21.qids[0]!==21||q21.sourceRawSha256!=='3546fb48c2bba3e18be75da0118defa83189bb3f9a741b2b36c28d57ce71c121') throw new Error('Q21_FRESH_STUDENT_BUNDLE_BINDING_INVALID');
if(current.rawSha256!=='bf01f97280750894b99b631e501f8990d40a14a82133def913b85c2f3d6f7e52'||current.rawBufferGitBlobSha1!=='b677fcfb7dca704aa461e3aacc69954856b51244') throw new Error('CURRENT_SOURCE_SHA_UNEXPECTED');
const q21row=q21.rows[0]; if(q21row.qid!==21) throw new Error('Q21_ROW_MISSING');
const rows=base.rows.map(r=>r.qid===21?structuredClone(q21row):structuredClone(r));
const input={schemaVersion:'JS_ARCHIVE_STUDENT_BUNDLE_V2',sourceRawSha256:current.rawSha256,sourceRawBlobSha1:current.rawBufferGitBlobSha1,questionCount:24,qids:base.qids,whitelist:base.whitelist,rows};
if(fs.existsSync(inputOut)) throw new Error('COMPOSITE_INPUT_OUTPUT_EXISTS');
fs.writeFileSync(inputOut,JSON.stringify(input,null,2)+'\n',{encoding:'utf8',flag:'wx'});
console.log(JSON.stringify({inputOut,inputSha256:(await import('node:crypto')).createHash('sha256').update(fs.readFileSync(inputOut)).digest('hex'),currentSourceRawSha256:current.rawSha256,currentSourceBlobSha1:current.rawBufferGitBlobSha1,questionCount:rows.length,qids:input.qids,q19StudentPayloadSha256:rows.find(r=>r.qid===19).studentPayloadSha256,q20StudentPayloadSha256:rows.find(r=>r.qid===20).studentPayloadSha256,q21StudentPayloadSha256:rows.find(r=>r.qid===21).studentPayloadSha256,assetCounts:rows.filter(r=>r.assets?.length).map(r=>({qid:r.qid,count:r.assets.length}))},null,2));